package com.petbanter;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.ArrayList;
import java.util.List;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class DialogueCatalog
{
    private static final String RESOURCE = "/pet-banter-dialogue.json";
    private final Map<String, List<String>> shared;
    private final Map<String, DialogueProfile> profiles;
    private final Map<String, String> transmogParents;

    @Inject
    public DialogueCatalog(Gson gson)
    {
        try (Reader reader = new InputStreamReader(
            DialogueCatalog.class.getResourceAsStream(RESOURCE), StandardCharsets.UTF_8))
        {
            CatalogFile file = gson.fromJson(reader, CatalogFile.class);
            shared = file.shared == null ? Collections.emptyMap() : file.shared;
            profiles = file.profiles == null ? Collections.emptyMap() : file.profiles;
            transmogParents = file.transmogParents == null ? Collections.emptyMap() : file.transmogParents;
        }
        catch (Exception ex)
        {
            throw new IllegalStateException("Unable to load Pet Banter dialogue catalog", ex);
        }
    }

    public List<String> linesFor(String petName)
    {
        String normalized = petName == null ? "" : petName.toLowerCase(Locale.ROOT);
        for (Map.Entry<String, DialogueProfile> entry : profiles.entrySet())
        {
            if (entry.getValue().transmogs != null)
            {
                for (Map.Entry<String, DialogueProfile> transmog : entry.getValue().transmogs.entrySet())
                {
                    if (matches(normalized, transmog.getKey()))
                    {
                        return combinedLines(transmog.getValue().lines);
                    }
                }
            }
            if (matches(normalized, entry.getKey()))
            {
                return combinedLines(entry.getValue().lines);
            }
        }
        return Collections.emptyList();
    }

    public int authoredLineCount(String petName)
    {
        String normalized = petName == null ? "" : petName.toLowerCase(Locale.ROOT);
        for (Map.Entry<String, DialogueProfile> entry : profiles.entrySet())
        {
            if (entry.getValue().transmogs != null)
            {
                for (Map.Entry<String, DialogueProfile> transmog : entry.getValue().transmogs.entrySet())
                {
                    if (matches(normalized, transmog.getKey()))
                    {
                        return transmog.getValue().lines == null ? 0 : transmog.getValue().lines.size();
                    }
                }
            }
            if (matches(normalized, entry.getKey()))
            {
                return entry.getValue().lines == null ? 0 : entry.getValue().lines.size();
            }
        }
        return 0;
    }

    private List<String> combinedLines(List<String> profileLines)
    {
        LinkedHashSet<String> unique = new LinkedHashSet<>();
        if (profileLines != null)
        {
            unique.addAll(profileLines);
        }
        unique.addAll(shared.getOrDefault("fallback", Collections.emptyList()));
        return new ArrayList<>(unique);
    }

    public String sharedLine(String context, int index)
    {
        List<String> lines = shared.getOrDefault(context, Collections.emptyList());
        return lines.isEmpty() ? null : lines.get(Math.floorMod(index, lines.size()));
    }

    public String contextLine(String petName, String context, int index)
    {
        String normalized = petName == null ? "" : petName.toLowerCase(Locale.ROOT);
        for (Map.Entry<String, DialogueProfile> entry : profiles.entrySet())
        {
            if (entry.getValue().transmogs != null)
            {
                for (Map.Entry<String, DialogueProfile> transmog : entry.getValue().transmogs.entrySet())
                {
                    if (normalized.contains(transmog.getKey().toLowerCase(Locale.ROOT)))
                    {
                        String line = lineFromContext(transmog.getValue(), context, index);
                        if (line != null)
                        {
                            return line;
                        }
                    }
                }
            }
            if (normalized.contains(entry.getKey().toLowerCase(Locale.ROOT)))
            {
                String line = lineFromContext(entry.getValue(), context, index);
                if (line != null)
                {
                    return line;
                }
            }
        }
        String parent = transmogParent(petName);
        if (parent != null && !parent.equalsIgnoreCase(petName))
        {
            return contextLine(parent, context, index);
        }
        return null;
    }

    private String lineFromContext(DialogueProfile profile, String context, int index)
    {
        if (profile.contexts == null)
        {
            return null;
        }
        List<String> lines = profile.contexts.get(context);
        return lines == null || lines.isEmpty() ? null : lines.get(Math.floorMod(index, lines.size()));
    }

    private boolean matches(String normalizedName, String profileName)
    {
        String normalizedProfile = profileName.toLowerCase(Locale.ROOT);
        String withoutPetPrefix = normalizedProfile.startsWith("pet ")
            ? normalizedProfile.substring(4) : normalizedProfile;
        String compactName = normalizedName.replace("'", "");
        String compactProfile = normalizedProfile.replace("'", "");
        String compactWithoutPet = withoutPetPrefix.replace("'", "");
        return normalizedName.equals(normalizedProfile)
            || normalizedName.equals(withoutPetPrefix)
            || normalizedName.equals("pet " + withoutPetPrefix)
            || normalizedName.startsWith(normalizedProfile + " jr")
            || normalizedName.contains(normalizedProfile)
            || compactName.equals(compactProfile)
            || compactName.equals(compactWithoutPet)
            || compactName.startsWith(compactProfile + " jr")
            || compactName.startsWith(compactWithoutPet + " jr")
            || compactName.contains(compactProfile);
    }

    public List<String> sharedLines(String context)
    {
        return shared.getOrDefault(context, Collections.emptyList());
    }

    public String transmogParent(String variantName)
    {
        if (variantName == null)
        {
            return null;
        }
        return transmogParents.get(variantName.toLowerCase(Locale.ROOT));
    }

    public String profileInteraction(String petName, int index)
    {
        String normalized = petName == null ? "" : petName.toLowerCase(Locale.ROOT);
        for (Map.Entry<String, DialogueProfile> entry : profiles.entrySet())
        {
            if (entry.getValue().transmogs != null)
            {
                for (Map.Entry<String, DialogueProfile> transmog : entry.getValue().transmogs.entrySet())
                {
                    if (matches(normalized, transmog.getKey())
                        && transmog.getValue().interactions != null
                        && !transmog.getValue().interactions.isEmpty())
                    {
                        List<String> lines = transmog.getValue().interactions;
                        return lines.get(Math.floorMod(index, lines.size()));
                    }
                }
            }
            if (matches(normalized, entry.getKey())
                && entry.getValue().interactions != null && !entry.getValue().interactions.isEmpty())
            {
                List<String> lines = entry.getValue().interactions;
                return lines.get(Math.floorMod(index, lines.size()));
            }
        }
        return null;
    }

    private static class CatalogFile
    {
        Map<String, List<String>> shared;
        Map<String, String> transmogParents;
        Map<String, DialogueProfile> profiles;
    }

    private static class DialogueProfile
    {
        String personality;
        List<String> lines;
        List<String> interactions;
        Map<String, List<String>> contexts;
        Map<String, DialogueProfile> transmogs;
    }
}

package com.petbanter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("petbanter")
public interface PetBanterConfig extends Config
{
    @ConfigItem(
        keyName = "enabled",
        name = "Enable Pet Banter",
        description = "Allow your pet to react to gameplay events"
    )
    default boolean enabled()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showThoughts",
        name = "Show Thought Bubbles",
        description = "Show thoughts above non-speaking pets"
    )
    default boolean showThoughts()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showChatReactions",
        name = "Show Chat Reactions",
        description = "Show pet reactions in the local chat box"
    )
    default boolean showChatReactions()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showPetInteractions",
        name = "Show Pet Interactions",
        description = "Allow nearby recognized pets to exchange dialogue"
    )
    default boolean showPetInteractions()
    {
        return true;
    }

    @Range(min = 1, max = 15)
    @ConfigItem(
        keyName = "interactionRange",
        name = "Nearby Pet Range",
        description = "Maximum same-plane distance for pet-to-pet interactions"
    )
    default int interactionRange()
    {
        return 5;
    }

}

package com.petbanter;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import java.util.concurrent.ThreadLocalRandom;

@Slf4j
@PluginDescriptor(
    name = "Pet Banter",
    description = "Brings OSRS pets to life with contextual reactions and thoughts",
    tags = {"pet", "follower", "companion"}
)
public class PetBanterPlugin extends Plugin
{
    private static final long MIN_REACTION_DELAY_MILLIS = 28_000L;
    private static final long MAX_REACTION_DELAY_MILLIS = 148_000L;
    @Inject
    private PetBanterConfig config;

    @Inject
    private PetTracker petTracker;

    @Inject
    private Client client;

    @Inject
    private ReactionEngine reactionEngine;

    private int lastFollowerId = -1;
    private String lastFollowerName;
    private long nextReactionAtMillis;
    private int reactionIndex;
    private boolean firstReaction;
    private NPC activeFollower;
    private ReactionContext pendingContext = ReactionContext.IDLE;
    private long pendingContextUntilMillis;

    @Override
    protected void startUp()
    {
        log.info("Pet Banter started!");
    }

    @Override
    protected void shutDown()
    {
        log.info("Pet Banter stopped!");
        clearOverheadText();
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!config.enabled())
        {
            clearOverheadText();
            pendingContext = ReactionContext.IDLE;
            pendingContextUntilMillis = 0;
            return;
        }
        int followerId = petTracker.getFollowerId();
        String followerName = petTracker.getFollowerName();
        String previousFollowerName = lastFollowerName;
        boolean followerChanged = followerId != lastFollowerId;
        boolean nameChanged = !java.util.Objects.equals(followerName, lastFollowerName);
        if (followerChanged || nameChanged)
        {
            log.debug("Follower changed: {}", followerName);
            lastFollowerId = followerId;
            lastFollowerName = followerName;
            nextReactionAtMillis = 0;
            firstReaction = previousFollowerName == null || "None".equals(previousFollowerName);
        }
        if (followerId == -1 || !config.showThoughts())
        {
            clearOverheadText();
            return;
        }
        if (System.currentTimeMillis() >= nextReactionAtMillis)
        {
            PetPersonality personality = PetPersonality.fromName(petTracker.getFollowerName());
            ReactionContext context;
            if (firstReaction)
            {
                context = ReactionContext.NEW_FOLLOWER;
            }
            else if (nameChanged && previousFollowerName != null && !"None".equals(previousFollowerName))
            {
                context = ReactionContext.METAMORPHOSIS;
            }
            else if (client.getLocalPlayer() != null
                && client.getLocalPlayer().getHealthRatio() >= 0
                && client.getLocalPlayer().getHealthRatio() < 30)
            {
                context = ReactionContext.DANGER;
            }
            else if (pendingContext == ReactionContext.LOOT
                && System.currentTimeMillis() <= pendingContextUntilMillis)
            {
                context = ReactionContext.LOOT;
            }
            else
            {
                context = ReactionContext.IDLE;
            }
            firstReaction = false;
            reactionIndex++;
            String reaction = reactionEngine.reaction(followerName, context, reactionIndex);
            activeFollower = petTracker.getFollower();
            if (activeFollower == null)
            {
                nextReactionAtMillis = System.currentTimeMillis() + MIN_REACTION_DELAY_MILLIS;
                return;
            }
            activeFollower.setOverheadText(reaction);
            activeFollower.setOverheadCycle(client.getGameCycle() + 100);
            if (config.showChatReactions())
            {
                client.addChatMessage(ChatMessageType.NPC_SAY, petTracker.getFollowerName(), reaction, null);
            }
            java.util.List<NPC> nearbyPets = config.showPetInteractions()
                ? petTracker.getNearbyKnownPets(config.interactionRange()) : java.util.Collections.emptyList();
            int interactionsShown = 0;
            for (NPC nearbyPet : nearbyPets)
            {
                if (config.showChatReactions())
                {
                    String opening = reactionEngine.nearbyInteraction(followerName,
                        nearbyPet.getName(), reactionIndex);
                    String reply = reactionEngine.nearbyInteraction(nearbyPet.getName(),
                        followerName, reactionIndex + 1);
                    client.addChatMessage(ChatMessageType.NPC_SAY, followerName, opening, null);
                    client.addChatMessage(ChatMessageType.NPC_SAY, nearbyPet.getName(), reply, null);
                }
                interactionsShown++;
                if (interactionsShown >= 3)
                {
                    break;
                }
            }
            nextReactionAtMillis = System.currentTimeMillis() + ThreadLocalRandom.current()
                .nextLong(MIN_REACTION_DELAY_MILLIS, MAX_REACTION_DELAY_MILLIS + 1);
            pendingContext = ReactionContext.IDLE;
            pendingContextUntilMillis = 0;
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        String message = event.getMessage();
        if (message == null)
        {
            return;
        }
        String normalized = message.toLowerCase(java.util.Locale.ROOT);
        if (normalized.contains("you receive") || normalized.contains("you found")
            || normalized.contains("you get some"))
        {
            pendingContext = ReactionContext.LOOT;
            pendingContextUntilMillis = System.currentTimeMillis() + 10_000L;
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        clearOverheadText();
        lastFollowerId = -1;
        lastFollowerName = null;
        nextReactionAtMillis = 0;
        firstReaction = true;
        pendingContext = ReactionContext.IDLE;
        pendingContextUntilMillis = 0;
    }

    private void clearOverheadText()
    {
        if (activeFollower != null)
        {
            activeFollower.setOverheadText(null);
            activeFollower = null;
        }
    }

    @Provides
    PetBanterConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(PetBanterConfig.class);
    }
}

package com.petbanter;

import java.util.Locale;

public enum PetPersonality
{
    GIANT_SQUIRREL("Giant Squirrel"),
    DARK_ACORN("Dark Acorn"),
    GENERIC("Pet");

    private final String displayName;

    PetPersonality(String displayName)
    {
        this.displayName = displayName;
    }

    public static PetPersonality fromName(String name)
    {
        if (name == null)
        {
            return GENERIC;
        }
        String normalized = name.toLowerCase(Locale.ROOT);
        if (normalized.contains("giant squirrel"))
        {
            return GIANT_SQUIRREL;
        }
        if (normalized.contains("dark acorn") || normalized.contains("dark squirrel"))
        {
            return DARK_ACORN;
        }
        return GENERIC;
    }

    public String getDisplayName()
    {
        return displayName;
    }
}

