    public String reaction(PetPersonality personality, ReactionContext context, int index)
    {
        String[] options = reactions.get(personality);
        if (context == ReactionContext.NEW_FOLLOWER)
        {
            return "Ready when you are.";
        }
        return options[Math.floorMod(index, options.length)];
    }

    public String reaction(String petName, ReactionContext context, int index)
    {
        if (context == ReactionContext.NEW_FOLLOWER)
        {
            return "Ready when you are.";
        }
        if (context == ReactionContext.METAMORPHOSIS && catalog != null)
        {
            String line = catalog.contextLine(petName, "metamorphosis", index);
            if (line == null)
            {
                line = catalog.sharedLine("metamorphosis", index);
            }
            if (line != null)
            {
                return line.replace("{pet}", petName == null ? "Pet" : petName);
            }
        }
        if (context == ReactionContext.DANGER && catalog != null)
        {
            String line = catalog.contextLine(petName, "danger", index);
            if (line == null)
            {
                line = catalog.sharedLine("danger", index);
            }
            if (line != null)
            {
                return line.replace("{pet}", petName == null ? "Pet" : petName);
            }
        }
        if (context == ReactionContext.LOOT && catalog != null)
        {
            String line = catalog.contextLine(petName, "loot", index);
            if (line == null)
            {
                line = catalog.sharedLine("loot", index);
            }
            if (line != null)
            {
                return line.replace("{pet}", petName == null ? "Pet" : petName);
            }
        }
        if (context == ReactionContext.IDLE && catalog != null && index % 5 == 0)
        {
            String line = catalog.contextLine(petName, "travel", index);
            if (line == null)
            {
                line = catalog.sharedLine("travel", index);
            }
            if (line != null)
            {
                return line.replace("{pet}", petName == null ? "Pet" : petName);
            }
        }
        String normalized = petName == null ? "" : petName.toLowerCase(Locale.ROOT);
        if (catalog != null)
        {
            String displayName = petName == null || petName.trim().isEmpty() ? "Pet" : petName.trim();
            java.util.List<String> catalogLines = catalog.linesFor(petName);
            if (!catalogLines.isEmpty())
            {
                return catalogLines.get(Math.floorMod(index, catalogLines.size())).replace("{pet}", displayName);
            }
        }
        for (Map.Entry<String, String[]> entry : namedReactions.entrySet())
        {
            if (normalized.contains(entry.getKey()))
            {
                String[] lines = entry.getValue();
                return lines[Math.floorMod(index, lines.length)];
            }
        }
        if (catalog != null)
        {
            java.util.List<String> sharedLines = catalog.sharedLines("fallback");
            if (!sharedLines.isEmpty())
            {
                String displayName = petName == null || petName.trim().isEmpty() ? "Pet" : petName.trim();
                return sharedLines.get(Math.floorMod(index, sharedLines.size())).replace("{pet}", displayName);
            }
        }
        String displayName = petName == null || petName.trim().isEmpty() ? "Pet" : petName.trim();
        String[] fallback = {
            displayName + " is on patrol.",
            displayName + " approves this adventure.",
            displayName + " would like a snack.",
            displayName + " has a thought about that.",
            displayName + " is keeping an eye on things."
        };
        return fallback[Math.floorMod(index, fallback.length)];
    }

    public String interaction(PetPersonality speaker, PetPersonality listener, int index)
    {
        if (speaker == PetPersonality.DARK_ACORN || listener == PetPersonality.DARK_ACORN)
        {
            return "The shadows have company.";
        }
        return index % 2 == 0 ? "Race you to the next tree!" : "Try not to lose your acorns.";
    }

    public String nearbyInteraction(String petName, int index)
    {
        if (catalog != null)
        {
            String profileLine = catalog.profileInteraction(petName, index);
            if (profileLine != null)
            {
                return profileLine;
            }
            String line = catalog.sharedLine("nearbyPet", index);
            if (line != null)
            {
                return line.replace("{pet}", petName == null ? "Pet" : petName);
            }
        }
        return interaction(PetPersonality.fromName(petName), PetPersonality.GENERIC, index);
    }

    public String nearbyInteraction(String speakerName, String listenerName, int index)
    {
        if (catalog != null)
        {
            String speakerLine = catalog.profileInteraction(speakerName, index);
            if (speakerLine != null)
            {
                return speakerLine;
            }
            String listenerLine = catalog.profileInteraction(listenerName, index + 1);
            if (listenerLine != null)
            {
                return listenerLine;
            }
        }
        return nearbyInteraction(listenerName, index);
    }
}

package com.petbanter;

import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.HashSet;

public class DialogueCatalogTest
{
    @Test
    public void loadsNamedProfilesAndSharedContexts()
    {
        DialogueCatalog catalog = new DialogueCatalog(new Gson());
        assertTrue(catalog.linesFor("Phoenix").size() >= 100);
        assertEquals(catalog.linesFor("Phoenix").size(),
            new HashSet<>(catalog.linesFor("Phoenix")).size());
        assertTrue(catalog.linesFor("Dark Squirrel").contains("The shadows are listening."));
        assertTrue(catalog.linesFor("Dark Squirrel").size() >= 100);
        assertTrue(catalog.sharedLines("fallback").size() >= 100);
        assertTrue(catalog.sharedLine("travel", 0).length() > 0);
        assertEquals("Race you to the next tree.",
            catalog.profileInteraction("Giant Squirrel", 1));
        ReactionEngine engine = new ReactionEngine(catalog);
        assertTrue(engine.nearbyInteraction("Giant Squirrel", "Dark Squirrel", 0).length() > 0);
        assertTrue(catalog.linesFor("Puppadile").size() >= 100);
        assertTrue(catalog.linesFor("Greatish Guardian").size() >= 100);
        assertTrue(catalog.linesFor("Elidinis' Guardian").size() >= 100);
        assertTrue(catalog.linesFor("Callisto Cub (retro)").size() >= 100);
        assertTrue(catalog.linesFor("Zebo").size() >= 100);
        assertTrue(catalog.linesFor("Tumeken's Damaged Guardian").size() >= 100);
        assertTrue(catalog.linesFor("Vanguard").size() >= 100);
        assertEquals("olmlet", catalog.transmogParent("Vanguard"));
        assertEquals("giant squirrel", catalog.transmogParent("Dark Squirrel"));
        assertEquals("pet dark core", catalog.transmogParent("Corporeal Critter"));
        assertTrue(catalog.linesFor("Penance Queen").contains("The next wave will test everything."));
        assertEquals("Good. Something finally understands the dark.",
            catalog.contextLine("Dark Squirrel", "danger", 0));
        assertEquals("Excellent. A crisis worthy of my entrance.",
            catalog.contextLine("Phoenix", "danger", 0));
        assertTrue(catalog.linesFor("Baby Blue Dragon").isEmpty());
        assertTrue(engine.reaction("A newly added transmog", ReactionContext.IDLE, 1).contains("newly added transmog"));
        for (String petName : PetRoster.names())
        {
            assertTrue("Too few authored lines for " + petName + " (" + catalog.authoredLineCount(petName) + ")",
                catalog.authoredLineCount(petName) >= 9);
            assertTrue("No dialogue for " + petName,
                engine.reaction(petName, ReactionContext.IDLE, 0).length() > 0);
        }
    }
}

